// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// CreatePlanningSession Start a planning session from a repository URL and ref or a problem statement
	// (POST /v1/planning-sessions)
	CreatePlanningSession(ctx context.Context, request CreatePlanningSessionRequestObject) (CreatePlanningSessionResponseObject, error)
	// GetPlanningSession Read a planning session
	// (GET /v1/planning-sessions/{sessionID})
	GetPlanningSession(ctx context.Context, request GetPlanningSessionRequestObject) (GetPlanningSessionResponseObject, error)
	// AcceptPlanningSession Accept the plan and record the binding
	// (POST /v1/planning-sessions/{sessionID}/accept)
	AcceptPlanningSession(ctx context.Context, request AcceptPlanningSessionRequestObject) (AcceptPlanningSessionResponseObject, error)
	// AnswerPlanningNeedsInput Answer outstanding Needs Input questions
	// (POST /v1/planning-sessions/{sessionID}/answers)
	AnswerPlanningNeedsInput(ctx context.Context, request AnswerPlanningNeedsInputRequestObject) (AnswerPlanningNeedsInputResponseObject, error)
	// GetPlanningBinding Read the Accept binding
	// (GET /v1/planning-sessions/{sessionID}/binding)
	GetPlanningBinding(ctx context.Context, request GetPlanningBindingRequestObject) (GetPlanningBindingResponseObject, error)
	// StartPlanningCompute Start package compute for an accepted session
	// (POST /v1/planning-sessions/{sessionID}/compute)
	StartPlanningCompute(ctx context.Context, request StartPlanningComputeRequestObject) (StartPlanningComputeResponseObject, error)
	// ListPlanningEvents Read recorded planning events
	// (GET /v1/planning-sessions/{sessionID}/events)
	ListPlanningEvents(ctx context.Context, request ListPlanningEventsRequestObject) (ListPlanningEventsResponseObject, error)
	// PostPlanningTurn Run one planning turn
	// (POST /v1/planning-sessions/{sessionID}/turns)
	PostPlanningTurn(ctx context.Context, request PostPlanningTurnRequestObject) (PostPlanningTurnResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

